"""Shared rules: id patterns, the repo root, safe paths inside named roots, canonical JSON, terminal-safe text."""
from __future__ import annotations

import hashlib
import json
import os
import re
import secrets
from datetime import datetime, timezone
from pathlib import Path
from typing import Any

ALERT_ID = re.compile(r"^A-\d{3}$")
EVENT_ID = re.compile(r"^E-\d{6}$")
HOST = re.compile(r"^(WS|SRV)-\d{2}$")
ACTION_ID = re.compile(r"^ACT-\d{3}$")
RUN_ID = re.compile(r"^\d{8}T\d{6}Z-(mock|live)$")
RECORDING = re.compile(r"^live-\d{8}$")
# Process entity ids are generated by the dataset script: "P-" + 12 hex characters.
ENTITY_ID = re.compile(r"^P-[0-9a-f]{12}$")

# checklist/ = the buyer's checklist the console renders; evals/intel_key.json = expected intel answers (read-only).
READ_ROOTS = ("data", "out", "evals/recorded", "evals/answer_key.json", "checklist", "evals/intel_key.json")
# The eval runner also writes its two result files (the README table source); nothing else under evals/.
WRITE_ROOTS = ("out", "evals/recorded", "evals/results.md", "evals/results.json")

_CONTROL = re.compile(r"[\x00-\x08\x0b-\x1f\x7f-\x9f\u2028\u2029\u202a-\u202e\u2066-\u2069\ud800-\udfff]")


def recording_date(recording: Any) -> str | None:
    """The one date a reader sees for a recorded run: the date in its id (live-20261028 -> 2026-10-28). Turn and audit
    trail stamps stay UTC and can fall on the next day. None for anything that is not a recording id."""
    if not isinstance(recording, str) or not RECORDING.fullmatch(recording):
        return None
    digits = recording[len("live-"):]
    return f"{digits[:4]}-{digits[4:6]}-{digits[6:]}"


class UsageError(Exception):
    """Bad input from the person or the environment: the CLI prints one line and exits 2."""


def check_id(pattern: re.Pattern, value: Any, what: str, error: type[Exception] = UsageError) -> str:
    if not isinstance(value, str) or not pattern.fullmatch(value):
        raise error(f"bad {what}: expected {pattern.pattern}")
    return value


class Repo:
    """The repo folder `asa` runs from. Every path it hands out stays inside a named root."""

    def __init__(self, base: Path | str | None = None):
        self.base = Path(base if base is not None else Path.cwd()).resolve()
        if not (self.base / "data" / "alerts.json").is_file():
            raise UsageError("run asa from the repo folder (./data/alerts.json not found)")

    def path(self, root: str, *parts: str, write: bool = False) -> Path:
        allowed = WRITE_ROOTS if write else READ_ROOTS + WRITE_ROOTS
        if root not in allowed:
            raise UsageError(f"root not allowed: {root}")
        root_path = (self.base / root).resolve()
        target = root_path.joinpath(*parts).resolve()
        if target != root_path and root_path not in target.parents:
            raise UsageError(f"path leaves its root: {root}")
        return target

    def rel(self, path: Path) -> str:
        """Repo-relative, forward-slash path for printing and storing (never absolute)."""
        return Path(path).resolve().relative_to(self.base).as_posix()


def run_dir_arg(repo: Repo, text: str) -> Path:
    """A run folder given on the command line: out/runs/<run_id>/<alert_id>, checked part by part (exit 2 otherwise)."""
    if not isinstance(text, str) or len(text) > 400:
        raise UsageError("bad run folder: expected out/runs/<run_id>/<alert_id>")
    path = Path(text)
    runs = repo.path("out", "runs")
    try:
        parts = (path if path.is_absolute() else repo.base / path).resolve().relative_to(runs).parts
    except ValueError:
        raise UsageError("bad run folder: expected out/runs/<run_id>/<alert_id>") from None
    if len(parts) != 2:
        raise UsageError("bad run folder: expected out/runs/<run_id>/<alert_id>")
    run_id, alert_id = check_id(RUN_ID, parts[0], "run id"), check_id(ALERT_ID, parts[1], "alert id")
    run_dir = repo.path("out", "runs", run_id, alert_id)
    if not (run_dir / "verdict.json").is_file():
        raise UsageError(f"no verdict.json in out/runs/{run_id}/{alert_id}")
    return run_dir


def output_file(run_dir: Path, name: str) -> Path:
    """A file the CLI writes inside a run folder: never a link, never outside the folder."""
    path = run_dir / name
    if path.is_symlink() or path.resolve().parent != run_dir.resolve():
        raise UsageError(f"refusing to write {name}: not a plain file in the run folder")
    return path


MAX_RECORD_BYTES = 32 * 1024 * 1024  # one JSON / JSONL record file (verdict, transcript, check, intel, approvals)


def read_capped(path: Path, what: str) -> bytes:
    """A file's bytes, refused (bad input, exit 2) past MAX_RECORD_BYTES without reading the rest."""
    with path.open("rb") as f:
        raw = f.read(MAX_RECORD_BYTES + 1)
    if len(raw) > MAX_RECORD_BYTES:
        raise UsageError(f"cannot read {what}: too large (over {MAX_RECORD_BYTES // (1024 * 1024)} MB)")
    return raw


def read_json(path: Path, what: str) -> Any:
    """A JSON file the CLI needs; a missing, broken or oversized one is bad input (exit 2), never a traceback."""
    try:
        return json.loads(read_capped(path, what).decode("utf-8"))
    except (OSError, ValueError, RecursionError) as exc:
        raise UsageError(f"cannot read {what}: {type(exc).__name__}") from None


def canonical_json(value: Any) -> str:
    return json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=False)


def sha256_json(value: Any) -> str:
    # surrogatepass: a lone surrogate from model input hashes instead of crashing (same bytes as UTF-8 otherwise)
    return hashlib.sha256(canonical_json(value).encode("utf-8", "surrogatepass")).hexdigest()


def clean_text(text: Any) -> str:
    """Terminal-safe: control characters (incl. ANSI escapes and bidi overrides) become '?'."""
    return _CONTROL.sub("?", str(text))


def write_json(path: Path, value: Any) -> None:
    """Write the whole file or nothing: a temp file in the same folder, then os.replace (atomic), so a failed write
    (disk full, a crash) never leaves a half-written verdict / check / intel file in place of the old one."""
    path.parent.mkdir(parents=True, exist_ok=True)
    # ASCII JSON never fails to encode: a lone surrogate from model output is written as an escape
    data = (json.dumps(value, indent=2) + "\n").encode("utf-8")
    tmp = path.with_name(f".{path.name}.{secrets.token_hex(6)}.tmp")
    flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_BINARY", 0) | getattr(os, "O_NOFOLLOW", 0)
    fd = os.open(tmp, flags, 0o644)
    try:
        try:
            view = memoryview(data)
            while view:
                view = view[os.write(fd, view):]
        finally:
            os.close(fd)
        os.replace(tmp, path)
    except BaseException:
        try:
            os.unlink(tmp)
        except FileNotFoundError:
            pass
        raise


def append_jsonl(path: Path, value: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("a", encoding="utf-8", newline="\n") as f:
        f.write(json.dumps(value, sort_keys=True) + "\n")


def read_jsonl(path: Path) -> list[dict]:
    with path.open(encoding="utf-8") as f:
        return [json.loads(line) for line in f if line.strip()]


def utc_now() -> datetime:
    return datetime.now(timezone.utc)


def new_run_id(mode: str, now: datetime | None = None) -> str:
    return (now or utc_now()).strftime("%Y%m%dT%H%M%SZ") + f"-{mode}"
